module comparator_4bit ( A,B,A_greater,A_equal,A -less);
 input  [3:0] A;  // 4-bit input A
    input  [3:0] B;   // 4-bit input B
    output  A_greater ; // A > B
    output  A_equal ;   // A == B
    output  A_less   ;   // A < B
    assign  A_greater  = (A > B) ? 1 : 0;
    assign  A_equal    = (A == B) ? 1 : 0;
    assign  A_less     = (A < B) ? 1 : 0;
endmodule
